#' @param influenceShowThreshold .
#' @param plotStyle .
#' @param plotPalette .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$designGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$design} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$categoryDistribution} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$separationGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$separation} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$separationInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$linearityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$linearity} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$linearityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$linearityPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$iiaGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$iia} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$iiaInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$goodnessOfFitGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$goodnessOfFit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$goodnessOfFitInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$discriminationGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$discrimination} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$discriminationInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$classificationGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$classification} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$classificationInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$multicollinearityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$multicollinearity} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$multicollinearityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$correlationMatrixGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$pearsonMatrixTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dcorMatrixTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$correlationMatrixNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$correlationComparisonGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$correlationComparisonTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$correlationComparisonInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$influenceGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$influence} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$influenceInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$influencePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$coefficientsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$coefficients} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coefficientsInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$design$asDF}
#'
#' \code{as.data.frame(results$design)}
#'
#' @export
multCheck <- function(
    data,
    dep,
    covs = NULL,
    factors = NULL,
    reportLang = "en",
    showPlots = TRUE,
    linShowPlots = TRUE,
    linSmoother = "none",
    linBins = 8,
    influenceShowPlots = TRUE,
    influenceLabelMode = "top5",
    influenceShowThreshold = TRUE,
    plotStyle = "clean",
    plotPalette = "blueOrange") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("multCheck requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(factors)) factors <- jmvcore::resolveQuo(jmvcore::enquo(factors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(factors), factors, NULL))

    for (v in dep) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in factors) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- multCheckOptions$new(
        dep = dep,
        covs = covs,
        factors = factors,
        reportLang = reportLang,
        showPlots = showPlots,
        linShowPlots = linShowPlots,
        linSmoother = linSmoother,
        linBins = linBins,
        influenceShowPlots = influenceShowPlots,
        influenceLabelMode = influenceLabelMode,
        influenceShowThreshold = influenceShowThreshold,
        plotStyle = plotStyle,
        plotPalette = plotPalette)

    analysis <- multCheckClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

